 async function loadFile(file?:File){if(!file)return;try{if(file.size>150000)throw Error();const x=JSON.parse(await file.text());const p=x.plan;if(x.schema!=='shadowcraft-v1'||!validStoredPlan(p,p?.classKey||'assassin'))throw Error();if((p.classKey||'assassin')!==classKey){notify(t('파일의 직업을 먼저 선택한 뒤 다시 불러오세요.'));return}setPlan({...p,classKey});notify(t('저장한 빌드를 불러왔습니다.'))}catch{notify(t('올바른 ASBC 빌드 파일이 아닙니다.'))}}
 function simulate(type:string){const dest=type==='flash'?(simPosition==='back'?'front':'back'):type==='walk'?'side':'back';setSimPosition(dest);const danger=simPhase==='circle'||simPhase===dest;setSimMessage(danger?'위험 구역에 도착했습니다. 이동 전에 착지 위치를 확인하세요.':dest==='side'?'안전한 측면으로 이동했습니다. 딜보다 패턴 회피를 우선하세요.':'안전한 위치입니다. 보스의 다음 패턴을 확인하며 공격하세요.')}
 if(!ready)return <div className="class-loading" role="status">{t('저장한 캐릭터와 계획을 복원하는 중…')}</div>;
