 {plannerTab&&review&&<div className="notice amber-notice"><AlertTriangle size={17}/>{t('새 데이터가 반영되었습니다. 추천 조합은 {0} 기준이므로 변경된 특화를 확인하세요.',[BASELINE])}<button onClick={()=>setTab('updates')}>{t('변경 기록 보기 →')}</button></div>}

