 {undo&&plannerTab&&<div className="notice" role="status"><span>{samePlan(plan,undo.after)?t(undo.kind==='purpose'?'플레이 목적을 변경했습니다.':'빌드를 적용했습니다.'):t('적용 이후 편집한 내용이 있습니다. 되돌리면 이 변경도 취소됩니다.')}</span><button className="button secondary" onClick={()=>{setPlan(undo.before);setUndo(null);notify(t('빌드 적용 전 계획으로 되돌렸습니다.'))}}>{t(undo.kind==='purpose'?'목적 변경 전으로 되돌리기':'빌드 적용 전으로 되돌리기')}</button></div>}
